# libcat

Small catalog service for the branch libraries. It ingests publisher feeds,
keeps the catalog in memory, and serves search, statistics and loan endpoints.

```
libcat/
  app.py            wiring (build_app) and the tiny router
  api/              request/response helpers and endpoint handlers
  services/         harvest, search, stats, loans
  store/            repository and secondary indexes
  util/             feed format, dates, text folding, cache
tests/              unit tests and end-to-end API tests
```

Run all tests with `bash test.sh`.
"""Catalog search: free text, subject and publication-year filters."""
from libcat.models import NotFound
from libcat.util.dates import display_year
from libcat.util.feed_format import first
from libcat.util.text import fold, tokens


class SearchService:
    def __init__(self, repo, settings):
        self.repo = repo
        self.settings = settings

    def get(self, record_id):
        record = self.repo.get(record_id)
        if record is None:
            raise NotFound(f"no record {record_id}")
        return record

    def search(self, text=None, subject=None, year_from=None, year_to=None, page=1, page_size=20):
        if year_from is not None and year_to is not None and year_from > year_to:
            raise ValueError("from must not be after to")
        candidates = None
        if year_from is not None or year_to is not None:
            candidates = self.repo.years.ids_between(year_from, year_to)
        if subject:
            by_subject = self.repo.subjects.ids_for(subject.lower())
            candidates = by_subject if candidates is None else candidates & by_subject
        if candidates is None:
            candidates = set(self.repo.all_ids())

        records = [self.repo.get(i) for i in candidates]
        if text:
            wanted = tokens(text)
            records = [r for r in records if wanted <= self._haystack(r)]

        records.sort(key=lambda r: (fold(r.title), r.id))
        total = len(records)
        start = (page - 1) * page_size
        items = [
            {"id": r.id, "title": r.title, "creators": r.creators, "year": display_year(first(r.date))}
            for r in records[start:start + page_size]
        ]
        return {"total": total, "page": page, "items": items}

    @staticmethod
    def _haystack(record):
        words = tokens(record.title)
        for creator in record.creators:
            words |= tokens(creator)
        return words
"""Aggregate views over the catalog, cached for the dashboard."""


class StatsService:
    def __init__(self, repo, cache):
        self.repo = repo
        self.cache = cache

    def years(self):
        return self.cache.get_or_compute("years", self._compute_years)

    def subjects(self):
        return self.cache.get_or_compute("subjects", self._compute_subjects)

    def _compute_years(self):
        counts = self.repo.years.counts()
        dated = set()
        for ids in self.repo.years.buckets().values():
            dated |= ids
        undated = sum(1 for i in self.repo.all_ids() if i not in dated)
        return {
            "years": [{"year": y, "count": counts[y]} for y in sorted(counts)],
            "undated": undated,
            "total": self.repo.count(),
        }

    def _compute_subjects(self):
        counts = self.repo.subjects.counts()
        ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
        return {"subjects": [{"subject": s, "count": c} for s, c in ranked]}
"""Publisher feed format.

A feed is a sequence of records separated by blank lines. Each line is
`key: value`. Lines starting with `#` are comments. A key may repeat inside
one record (several creators, several subjects, ...): repeated keys are kept
in order as a list, a key that appears once stays a plain string.
"""


def parse_feed(text):
    records, current = [], {}
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if line.startswith("#"):
            continue
        if not line:
            if current:
                records.append(current)
                current = {}
            continue
        if ":" not in line:
            raise ValueError(f"line {lineno}: expected 'key: value'")
        key, value = line.split(":", 1)
        key, value = key.strip().lower(), value.strip()
        if key in current:
            existing = current[key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                current[key] = [existing, value]
        else:
            current[key] = value
    if current:
        records.append(current)
    return records


def as_list(value):
    if value is None:
        return []
    if isinstance(value, list):
        return list(value)
    return [value]


def first(value):
    if isinstance(value, list):
        return value[0] if value else None
    return value
"""Text normalisation used for sorting and matching."""
import re
import unicodedata

_WORD = re.compile(r"[0-9a-z]+")
_LEADING_ARTICLES = ("the ", "a ", "an ")


def fold(text):
    """Lower-case, strip accents and leading articles for sort keys."""
    if not text:
        return ""
    decomposed = unicodedata.normalize("NFD", text)
    plain = "".join(ch for ch in decomposed if unicodedata.category(ch) != "Mn").lower().strip()
    for article in _LEADING_ARTICLES:
        if plain.startswith(article):
            return plain[len(article):]
    return plain


def tokens(text):
    return set(_WORD.findall(fold(text)))


def clean_title(title):
    title = " ".join(title.split())
    return title.rstrip(" /:;")
"""Date helpers for catalog metadata.

Publishers send partial ISO dates: `2019`, `2019-05`, `2019-05-01`, and some
older feeds use dots (`2019.05.01`).
"""
import datetime as _dt


def parse_date(text):
    """Parse a (possibly partial) date into a datetime.date, filling gaps with 1."""
    if not text:
        return None
    parts = text.strip().replace(".", "-").split("-")
    try:
        numbers = [int(p) for p in parts if p]
    except ValueError:
        return None
    if not numbers or len(numbers) > 3:
        return None
    year, month, day = (numbers + [1, 1])[:3]
    try:
        return _dt.date(year, month, day)
    except ValueError:
        return None


def years_of(value):
    """Publication years mentioned by a date field, as a set of ints."""
    if not value or len(value) < 4:
        return set()
    head = value[:4]
    if not all(ch.isdigit() for ch in head):
        return set()
    return {int(head)}


def display_year(text):
    parsed = parse_date(text)
    return str(parsed.year) if parsed else "n.d."
